// Pure material union. This file never changes navigation, collision or artwork.
export function insideConvex(p,poly,epsilon=1e-8){return poly.length>=3&&poly.every((a,i)=>{const b=poly[(i+1)%poly.length];return(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0])>=-epsilon;});}
export function convexHull(points){const sorted=[...new Map(points.map(p=>[p.join(','),p.slice()])).values()].sort((a,b)=>a[0]-b[0]||a[1]-b[1]);if(sorted.length<3)return sorted;const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]),half=ps=>{const result=[];for(const p of ps){while(result.length>1&&cross(result.at(-2),result.at(-1),p)<=0)result.pop();result.push(p);}return result;};return[...half(sorted).slice(0,-1),...half(sorted.slice().reverse()).slice(0,-1)];}
export function clipY(poly,yMax){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],aa=a[1]<=yMax,bb=b[1]<=yMax;if(aa)out.push(a.slice());if(aa!==bb){const f=(yMax-a[1])/(b[1]-a[1]);out.push([a[0]+f*(b[0]-a[0]),yMax]);}}return out;}
export function sweptFoot(a,b,probes){return convexHull([a,b].flatMap(p=>probes.map(([x,y])=>[p[0]+x,p[1]+y])));}
const segmentDistance=(p,a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],f=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)));return Math.hypot(p[0]-a[0]-f*dx,p[1]-a[1]-f*dy);};
export function createMaterialEnvelope(contract,{legalPoint}={}){if(typeof legalPoint!=='function')throw Error('Explicit current legalPoint mask required');if(contract.status!=='PROPOSED_GROUND_ONLY_NO_NAVIGATION_OR_CREATIVE_APPROVAL')throw Error('Proposed-only contract required');const parts=contract.union.polygons.map(p=>p.points.map(v=>v.slice())),join=contract.existingStreetJoin;const existingJoin=p=>Math.hypot(p[0]-join.endpoint[0],p[1]-join.endpoint[1])<=join.localRadius+1e-9&&join.points.slice(1).some((b,i)=>segmentDistance(p,join.points[i],b)<=join.width/2+1e-9)&&legalPoint(p);const paint=p=>Number.isFinite(p[0])&&Number.isFinite(p[1])&&p[1]<=contract.paintClampY+1e-9&&parts.some(poly=>insideConvex(p,poly))&&legalPoint(p);return Object.freeze({paintContains:paint,existingJoinContains:existingJoin,covered:p=>paint(p)||existingJoin(p)});}
